def greedy_next (x : Nat) : Nat := x * x - x + 1

def telescoping_identity (x : Nat) : Prop :=
  x * (greedy_next x - 1) - x * (x - 1) =
    (x - 1) * (greedy_next x - 1)

def check_range : Bool :=
  decide (∀ x : Fin 9, telescoping_identity (x.val + 2))
